def backfill_existing_bills(apps, schema_editor):
    # Existing bills keep their stored totals; derive the new breakdown fields.
    Bill = apps.get_model("crm", "Bill")
    for bill in Bill.objects.all().iterator():
        tax = Decimal(str(bill.tax_amount or 0))
        half = (tax / 2).quantize(Decimal("0.01"))
        bill.taxable_amount = bill.subtotal
        bill.cgst_amount = half
        bill.sgst_amount = tax - half
        bill.net_payable = bill.total_amount
        bill.save(update_fields=["taxable_amount", "cgst_amount", "sgst_amount", "net_payable"])


